insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('1ac738da-e6b4-5537-9ef5-d4a070466c1d', 'b8330436-7f80-51be-b374-b3824d468670', '{"en":"Solving quadratic equations","fr":"Résoudre une équation du second degré"}'::jsonb, '{"en":"# Quadratic equations\n\nA quadratic equation has the form **ax² + bx + c = 0**, where a ≠ 0.\n\n## 1. Solving by factorisation\n\nIf the expression factorises, set each factor to zero:\n\nx² − 5x + 6 = 0 → (x − 2)(x − 3) = 0 → **x = 2 or x = 3**\n\n## 2. The quadratic formula\n\nWhen factorising is hard, use:\n\n**x = (−b ± √(b² − 4ac)) / 2a**\n\n## 3. The discriminant Δ = b² − 4ac\n\n- Δ > 0: two distinct real roots\n- Δ = 0: one repeated root\n- Δ < 0: no real roots\n\n## Worked example\n\nSolve 2x² + 3x − 2 = 0.\n\na = 2, b = 3, c = −2, so Δ = 9 + 16 = 25 and √Δ = 5.\n\nx = (−3 + 5)/4 = **1/2** or x = (−3 − 5)/4 = **−2**.\n\n## Useful facts\n\nFor roots x₁ and x₂: **x₁ + x₂ = −b/a** and **x₁ · x₂ = c/a**.\n\n> Exam tip: always check your roots by substituting them back into the equation.","fr":"# Équations du second degré\n\nUne équation du second degré s''écrit **ax² + bx + c = 0**, avec a ≠ 0.\n\n## 1. Résolution par factorisation\n\nSi l''expression se factorise, on annule chaque facteur :\n\nx² − 5x + 6 = 0 → (x − 2)(x − 3) = 0 → **x = 2 ou x = 3**\n\n## 2. La formule générale\n\n**x = (−b ± √(b² − 4ac)) / 2a**\n\n## 3. Le discriminant Δ = b² − 4ac\n\n- Δ > 0 : deux racines réelles distinctes\n- Δ = 0 : une racine double\n- Δ < 0 : aucune racine réelle\n\n## Exemple corrigé\n\nRésoudre 2x² + 3x − 2 = 0.\n\na = 2, b = 3, c = −2, donc Δ = 9 + 16 = 25 et √Δ = 5.\n\nx = (−3 + 5)/4 = **1/2** ou x = (−3 − 5)/4 = **−2**.\n\n## À retenir\n\nPour les racines x₁ et x₂ : **x₁ + x₂ = −b/a** et **x₁ · x₂ = c/a**.\n\n> Conseil d''examen : vérifiez toujours vos racines en les remplaçant dans l''équation."}'::jsonb, 12, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
