  on conflict (id) do update set title = excluded.title, order_index = excluded.order_index, status = excluded.status;
insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('3ffe1c38-9d82-5e84-9884-4881fc864991', '89d0248b-9fb3-5f15-b8fa-ebd46ba5cbd0', '{"en":"Rules of differentiation","fr":"Règles de dérivation"}'::jsonb, '{"en":"# Rules of differentiation\n\nThe derivative f''(x) measures the rate of change (gradient) of f at x.\n\n## Standard results\n\n| f(x) | f''(x) |\n|---|---|\n| xⁿ | n·xⁿ⁻¹ |\n| sin x | cos x |\n| cos x | −sin x |\n| eˣ | eˣ |\n| ln x | 1/x |\n\n## Rules\n\n- **Product:** (uv)'' = u''v + uv''\n- **Quotient:** (u/v)'' = (u''v − uv'') / v²\n- **Chain:** d/dx f(g(x)) = f''(g(x)) · g''(x)\n\n## Stationary points\n\nSolve f''(x) = 0. Then use f''''(x): positive → minimum, negative → maximum.\n\n## Example\n\ny = x² − 6x + 1 → y'' = 2x − 6 = 0 → x = 3, and y'''' = 2 > 0, so it is a **minimum**.","fr":"# Règles de dérivation\n\n| f(x) | f''(x) |\n|---|---|\n| xⁿ | n·xⁿ⁻¹ |\n| sin x | cos x |\n| cos x | −sin x |\n| eˣ | eˣ |\n| ln x | 1/x |\n\n- **Produit :** (uv)'' = u''v + uv''\n- **Quotient :** (u/v)'' = (u''v − uv'') / v²\n- **Composée :** (f∘g)'' = (f''∘g) · g''\n\n## Points stationnaires\n\nOn résout f''(x) = 0, puis on étudie le signe de f''''(x)."}'::jsonb, 15, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
