insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('eb0a95f0-5244-5658-93ee-419c7116e57f', '3f8db855-fb49-5090-842e-b3e431ed4777', '{"en":"Amount of substance","fr":"Quantité de matière"}'::jsonb, '{"en":"# The mole concept\n\nOne **mole** contains Avogadro''s number of particles: **L ≈ 6.02 × 10²³ mol⁻¹**.\n\n## Key relationships\n\n- **n = m / M** (moles = mass ÷ molar mass)\n- **c = n / V** (concentration in mol/dm³, with V in dm³)\n- Number of particles = n × L\n\n## Molar mass\n\nAdd the relative atomic masses: M(CO₂) = 12 + 2 × 16 = **44 g/mol**.\n\n## Worked example\n\nHow many moles are in 36 g of water (M = 18 g/mol)? n = 36 / 18 = **2 mol**.\n\n> Remember: 1 dm³ = 1000 cm³.","fr":"# La mole\n\nUne **mole** contient **N_A ≈ 6,02 × 10²³** entités.\n\n- **n = m / M**\n- **C = n / V** (en mol/L)\n\nExemple : 36 g d''eau (M = 18 g/mol) → n = **2 mol**."}'::jsonb, 12, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
