insert into public.chapters (id, track_id, subject_id, title, order_index, status) values ('735037b0-3d27-509c-8650-bcdb8cf5549b', 'bddad6a8-d69f-5a41-8b7d-9d80ef717fc9', '6dd5a36f-8463-589c-8f76-af2673b788eb', '{"fr":"Polynômes du second degré","en":"Second-degree polynomials"}'::jsonb, 0, 'published')
  on conflict (id) do update set title = excluded.title, order_index = excluded.order_index, status = excluded.status;
insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('32f9be4f-7d97-56b5-81a6-02b467f44d65', '735037b0-3d27-509c-8650-bcdb8cf5549b', '{"fr":"Forme canonique, discriminant et signe","en":"Canonical form, discriminant and sign"}'::jsonb, '{"fr":"# Polynômes du second degré\n\nUn trinôme s''écrit **P(x) = ax² + bx + c**, avec a ≠ 0.\n\n## Forme canonique\n\n**P(x) = a[(x + b/2a)² − Δ/4a²]** où **Δ = b² − 4ac**.\n\nExemple : x² + 4x + 1 = (x + 2)² − 3.\n\n## Racines\n\n- Δ > 0 : x₁ = (−b − √Δ)/2a et x₂ = (−b + √Δ)/2a\n- Δ = 0 : racine double x₀ = −b/2a\n- Δ < 0 : pas de racine réelle\n\n## Somme et produit\n\n**S = x₁ + x₂ = −b/a** et **P = x₁ · x₂ = c/a**.\n\n## Signe du trinôme\n\n- Si Δ < 0, P(x) est toujours du **signe de a**.\n- Si Δ > 0, P(x) est du signe de a **à l''extérieur** des racines, du signe contraire **entre** les racines.","en":"# Second-degree polynomials\n\n**P(x) = ax² + bx + c**, a ≠ 0, with discriminant **Δ = b² − 4ac**.\n\n- Canonical form: x² + 4x + 1 = (x + 2)² − 3.\n- Sum of roots −b/a, product c/a.\n- If Δ < 0, P(x) always has the **sign of a**.\n- If Δ > 0, P(x) has the sign of a outside the roots and the opposite sign between them."}'::jsonb, 15, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
