insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('8bc2d5cb-8d5b-58bf-af4f-414cd3b72719', '623387e2-6546-52f5-8466-a28a66a915d6', '{"fr":"Travail d''une force et puissance","en":"Work done by a force and power"}'::jsonb, '{"fr":"# Travail et puissance\n\n## Travail d''une force constante\n\n**W = F × d × cos α**, en **joules (J)**, où α est l''angle entre la force et le déplacement.\n\n- α = 0 : travail moteur maximal, W = F·d\n- α = 90° : **travail nul**\n- α > 90° : travail résistant (négatif)\n\n## Travail du poids\n\n**W = m × g × h** (h : dénivellation), positif à la descente.\n\n## Puissance\n\n**P = W / t**, en **watts (W)**.","en":"# Work and power\n\n- **W = F × d × cos α** (joules). A force perpendicular to the motion does **no work**.\n- Work done by weight: **W = m g h**.\n- Power: **P = W / t** (watts)."}'::jsonb, 12, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
