insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('863747c5-bfb7-55de-b406-f70c67c8741c', '7a8f9820-c8e0-57b3-823a-43d756fa100b', '{"fr":"Suites arithmétiques et géométriques","en":"Arithmetic and geometric sequences"}'::jsonb, '{"fr":"# Suites arithmétiques et géométriques\n\n## Suite arithmétique de raison r\n\n- **uₙ = u₀ + n·r**\n- Somme de termes consécutifs : (nombre de termes) × (premier + dernier) / 2\n\n## Suite géométrique de raison q\n\n- **uₙ = u₀ · qⁿ**\n- Somme : u₀ (1 − qⁿ⁺¹)/(1 − q) si q ≠ 1\n\n## Convergence\n\nSi **|q| < 1**, alors qⁿ → 0 : la suite géométrique converge vers **0**.","en":"# Arithmetic and geometric sequences\n\n- Arithmetic: **uₙ = u₀ + n·r**\n- Geometric: **uₙ = u₀ · qⁿ**\n- If |q| < 1, a geometric sequence converges to 0."}'::jsonb, 15, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
