insert into public.chapters (id, track_id, subject_id, title, order_index, status) values ('cf51f09c-70bd-5c22-846c-658774a83d11', '1127b20b-443d-557f-bf50-99ed8a311a97', '6dd5a36f-8463-589c-8f76-af2673b788eb', '{"fr":"Nombres complexes","en":"Complex numbers"}'::jsonb, 0, 'published')
  on conflict (id) do update set title = excluded.title, order_index = excluded.order_index, status = excluded.status;
insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('18eb21e8-812f-539d-a3b4-5f24627839f9', 'cf51f09c-70bd-5c22-846c-658774a83d11', '{"fr":"Forme algébrique, module et conjugué","en":"Algebraic form, modulus and conjugate"}'::jsonb, '{"fr":"# Nombres complexes\n\nOn pose **i² = −1**. Tout complexe s''écrit **z = a + ib** (a = Re z, b = Im z).\n\n## Conjugué\n\n**z̄ = a − ib**, et z · z̄ = a² + b².\n\n## Module et argument\n\n- **|z| = √(a² + b²)**\n- Si z ≠ 0, un argument θ vérifie cos θ = a/|z| et sin θ = b/|z|.\n- Forme trigonométrique : **z = |z|(cos θ + i sin θ)**.\n\n## Exemples\n\n- |3 + 4i| = √(9 + 16) = **5**\n- (1 + i)² = 1 + 2i + i² = **2i**\n- arg(i) = **π/2**","en":"# Complex numbers\n\nWith **i² = −1**, every complex number is **z = a + ib**.\n\n- Conjugate: z̄ = a − ib.\n- Modulus: |z| = √(a² + b²), e.g. |3 + 4i| = 5.\n- (1 + i)² = 2i, and arg(i) = π/2."}'::jsonb, 15, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
